def divisors(x):
    div = []
    for j in range(2, int(x**0.5)+1):
        if x % j == 0:
            div += [j, x // j]
    return sorted(set(div))

def Prost(x):
    if x == 1:
        return False
    for i in range(2, int(x**0.5)+1):
        if x % i == 0:
            return False
    return True

cnt = 0
for x in range(2_900_000, 10**10):
    div = divisors(x)
    if len(div) == 2 and Prost(div[0]) and Prost(div[1]):
        if str(div[0]).count('0') == 1 and str(div[1]).count('0') == 1:
            print(x, max(div))
            cnt += 1
            if cnt == 5:
                break
